('iphone-pro', 'Smartphone Pro + audífonos', 'El último modelo, sellado de fábrica y con garantía.', '/img/premio-iphone.png', 'activa', 100, 50000, 25000, 'Lotería de Bogotá', '2026-11-05T22:30:00-05:00', '[{"position":"Premio mayor","title":"Smartphone Pro 256 GB","description":"Incluye audífonos inalámbricos y cargador.","value":6200000},{"position":"2.º premio","title":"$300.000 en efectivo","description":"Número invertido de las 2 últimas cifras.","value":300000}]'::jsonb, '["Juega con las 2 últimas cifras del premio mayor.","Puesto completo o media fracción.","Entrega personal o envío gratis a todo el país."]'::jsonb),
('efectivo-diario', '$3.000.000 en efectivo', 'La dinámica diaria: premio en efectivo el mismo día.', '/img/premio-efectivo.png', 'activa', 100, 35000, 17500, 'Chontico Noche', '2026-10-28T22:30:00-05:00', '[{"position":"Premio mayor","title":"$3.000.000","description":"Transferencia inmediata tras el resultado.","value":3000000},{"position":"Primeros 2 dígitos","title":"$150.000","description":"Si aciertas las 2 primeras cifras del resultado.","value":150000}]'::jsonb, '["Juega con las 2 últimas cifras del Chontico Noche.","Se pagan premios por transferencia el mismo día."]'::jsonb),
('smart-tv', 'Smart TV 75" + consola', 'Arma el combo de entretenimiento para tu casa.', '/img/premio-tv.png', 'proxima', 100, 40000, 20000, 'Lotería del Valle', '2026-11-25T22:30:00-05:00', '[{"position":"Premio mayor","title":"Smart TV 75\" 4K + consola","description":"Con dos controles y un juego incluido.","value":7500000}]'::jsonb, '["Juega con las 2 últimas cifras del premio mayor."]'::jsonb)
